import csv
import json
import math
from collections import Counter, defaultdict

# ── 1. Load & parse data ──────────────────────────────────────────────
rows = []
with open('/app/benchmark/data.csv', 'r', encoding='utf-8') as f:
    reader = csv.DictReader(f)
    for r in reader:
        rows.append({
            'year': int(r['Year']),
            'film': r['Film'].strip(),
            'composer_raw': r['Composer'].strip()
        })

# Split combined composer strings into individual lists
for r in rows:
    r['composers'] = [c.strip() for c in r['composer_raw'].split(',')]

# Build individual-level records for frequency analysis
individual_wins = []  # (year, film, individual_composer)
for r in rows:
    for c in r['composers']:
        individual_wins.append({
            'year': r['year'],
            'film': r['film'],
            'composer': c
        })

# ── 2. KPI computations ──────────────────────────────────────────────

all_composers = sorted(set(w['composer'] for w in individual_wins))
total_unique_composers = len(all_composers)

composer_win_count = Counter(w['composer'] for w in individual_wins)
max_wins = max(composer_win_count.values())
max_win_composers = sorted([c for c, n in composer_win_count.items() if n == max_wins])

# Repeat winner rate: a ceremony counts if ANY of its composers had won before
# Track composers who have won up to (not including) the current year
prior_winners = set()
repeat_ceremony_count = 0
for r in rows:
    is_repeat = any(c in prior_winners for c in r['composers'])
    if is_repeat:
        repeat_ceremony_count += 1
    prior_winners.update(r['composers'])
repeat_winner_rate = repeat_ceremony_count / len(rows)

# Decade with most unique winners
def decade_of(year):
    return (year // 10) * 10

decade_composers = defaultdict(set)
for w in individual_wins:
    dec = decade_of(w['year'])
    decade_composers[dec].add(w['composer'])

decade_unique_counts = {dec: len(composers) for dec, composers in decade_composers.items()}
best_decade = max(decade_unique_counts, key=decade_unique_counts.get)
best_decade_count = decade_unique_counts[best_decade]

# ── 3. Top composers ranking ─────────────────────────────────────────
top_composers = sorted(composer_win_count.items(), key=lambda x: (-x[1], x[0]))

# ── 4. Decade-by-decade breakdown ────────────────────────────────────
decades_info = {}
for dec in sorted(decade_composers.keys()):
    comps = decade_composers[dec]
    wins_in_decade = [w for w in individual_wins if decade_of(w['year']) == dec]
    win_counts_in_decade = Counter(w['composer'] for w in wins_in_decade)
    repeat_wins = sum(1 for c, n in win_counts_in_decade.items() if n > 1)
    decades_info[dec] = {
        'unique_winners': len(comps),
        'total_ceremonies': sum(1 for r in rows if decade_of(r['year']) == dec),
        'repeat_winners': repeat_wins,
        'top_in_decade': win_counts_in_decade.most_common(5)
    }

# ── 5. Era analysis ──────────────────────────────────────────────────
era_boundaries = {
    'Golden Age': (1934, 1959),
    'Silver Age': (1960, 1979),
    'Modern Era': (1980, 1999),
    'Contemporary Era': (2000, 2026)
}

era_analysis = {}
for era_name, (start, end) in era_boundaries.items():
    era_wins = [w for w in individual_wins if start <= w['year'] <= end]
    era_comp_counts = Counter(w['composer'] for w in era_wins)
    era_films = list(dict.fromkeys(w['film'] for w in era_wins))  # unique preserving order
    era_analysis[era_name] = {
        'start': start,
        'end': end,
        'ceremonies': sum(1 for r in rows if start <= r['year'] <= end),
        'unique_composers': len(set(w['composer'] for w in era_wins)),
        'top_composers': era_comp_counts.most_common(5),
        'films': era_films
    }

# ── 6. Notable milestones ────────────────────────────────────────────

# First-time winners (first ceremony year per composer)
composer_first_win = {}
for w in individual_wins:
    if w['composer'] not in composer_first_win:
        composer_first_win[w['composer']] = w['year']

# All wins per composer with years
composer_all_wins = defaultdict(list)
for w in individual_wins:
    composer_all_wins[w['composer']].append(w['year'])

# Longest gaps
gaps = []
for comp, years in composer_all_wins.items():
    if len(years) >= 2:
        sorted_years = sorted(years)
        for i in range(1, len(sorted_years)):
            gaps.append((comp, sorted_years[i-1], sorted_years[i], sorted_years[i] - sorted_years[i-1]))
gaps.sort(key=lambda x: -x[3])
longest_gap = gaps[0] if gaps else None

# Most recent winner info
most_recent = rows[-1]

# ── 7. Generate HTML report ──────────────────────────────────────────

def composer_name_html(name):
    """Escape and optionally style composer names."""
    return name.replace('&', '&amp;').replace('<', '&lt;').replace('>', '&gt;')

# Build top composers table rows
top_rows = []
for rank, (name, count) in enumerate(top_composers[:20], 1):
    years = sorted(composer_all_wins[name])
    films = []
    for w in individual_wins:
        if w['composer'] == name:
            films.append(w['film'])
    top_rows.append({
        'rank': rank,
        'name': composer_name_html(name),
        'wins': count,
        'years': ', '.join(str(y) for y in years),
        'films': ', '.join(films)
    })

# Build decade table data for Chart.js
decade_labels = []
decade_unique_data = []
decade_repeat_data = []
for dec in sorted(decades_info.keys()):
    info = decades_info[dec]
    label = f"{dec}s"
    decade_labels.append(label)
    decade_unique_data.append(info['unique_winners'])
    decade_repeat_data.append(info['repeat_winners'])

# Build era chart data
era_chart_labels = list(era_analysis.keys())
era_unique_data = [era_analysis[e]['unique_composers'] for e in era_chart_labels]
era_ceremony_data = [era_analysis[e]['ceremonies'] for e in era_chart_labels]

# Composer bar chart (top 12)
top12 = top_composers[:12]
composer_chart_labels = [c for c, n in top12]
composer_chart_data = [n for c, n in top12]

# Win distribution (1-win, 2-win, etc.)
win_distribution = Counter(composer_win_count.values())
dist_labels = sorted(win_distribution.keys())
dist_data = [win_distribution[k] for k in dist_labels]

# Decade table for HTML
decade_table_rows = []
for dec in sorted(decades_info.keys()):
    info = decades_info[dec]
    label = f"{dec}s"
    if dec == 1930:
        label = "1934–1939"
    elif dec == 2020:
        label = "2020–2026"
    decade_table_rows.append({
        'decade': label,
        'ceremonies': info['total_ceremonies'],
        'unique': info['unique_winners'],
        'repeat': info['repeat_winners'],
        'top_name': info['top_in_decade'][0][0] if info['top_in_decade'] else '',
        'top_wins': info['top_in_decade'][0][1] if info['top_in_decade'] else 0
    })

# Era table
era_table_rows = []
for era_name in era_chart_labels:
    e = era_analysis[era_name]
    era_table_rows.append({
        'era': era_name,
        'period': f"{e['start']}–{e['end']}",
        'ceremonies': e['ceremonies'],
        'unique': e['unique_composers'],
        'top_name': e['top_composers'][0][0] if e['top_composers'] else '',
        'top_wins': e['top_composers'][0][1] if e['top_composers'] else 0
    })

# Milestones
first_winner = rows[0]
last_winner = rows[-1]

# Repeats summary
repeat_composers = [(c, n) for c, n in top_composers if n >= 2]
repeat_count = len(repeat_composers)

html = f'''<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>Nine Decades of Oscar-Winning Scores (1934–2026)</title>
<script src="https://cdn.jsdelivr.net/npm/chart.js@4.4.0/dist/chart.umd.min.js"></script>
<style>
  :root {{
    --gold: #C8A951;
    --gold-light: #F5E6B8;
    --dark: #1A1A2E;
    --darker: #0F0F1A;
    --card-bg: #16213E;
    --text: #E8E8E8;
    --text-secondary: #A0A0B0;
    --accent: #C8A951;
    --border: #2A2A4A;
  }}
  * {{ margin: 0; padding: 0; box-sizing: border-box; }}
  body {{
    font-family: 'Segoe UI', system-ui, -apple-system, sans-serif;
    background: var(--darker);
    color: var(--text);
    line-height: 1.7;
  }}

  /* ── Hero ── */
  .hero {{
    background: linear-gradient(135deg, #0F0F1A 0%, #1A1A2E 50%, #16213E 100%);
    border-bottom: 3px solid var(--gold);
    padding: 60px 40px 50px;
    text-align: center;
  }}
  .hero h1 {{
    font-size: 2.6em;
    font-weight: 700;
    color: var(--gold);
    letter-spacing: -0.02em;
    margin-bottom: 12px;
    line-height: 1.2;
  }}
  .hero .subtitle {{
    font-size: 1.15em;
    color: var(--text-secondary);
    max-width: 720px;
    margin: 0 auto;
    font-style: italic;
  }}

  /* ── Container ── */
  .container {{ max-width: 1100px; margin: 0 auto; padding: 0 30px; }}

  /* ── KPI Cards ── */
  .kpi-grid {{
    display: grid;
    grid-template-columns: repeat(4, 1fr);
    gap: 20px;
    margin: -30px auto 50px;
    position: relative;
    z-index: 2;
  }}
  .kpi-card {{
    background: var(--card-bg);
    border: 1px solid var(--border);
    border-radius: 12px;
    padding: 28px 22px;
    text-align: center;
    box-shadow: 0 4px 20px rgba(0,0,0,0.3);
  }}
  .kpi-card .value {{
    font-size: 2.6em;
    font-weight: 800;
    color: var(--gold);
    line-height: 1.1;
    margin-bottom: 6px;
  }}
  .kpi-card .label {{
    font-size: 0.85em;
    color: var(--text-secondary);
    text-transform: uppercase;
    letter-spacing: 0.06em;
  }}

  /* ── Sections ── */
  section {{ margin-bottom: 56px; }}
  section h2 {{
    font-size: 1.75em;
    font-weight: 700;
    color: var(--gold);
    border-bottom: 2px solid var(--border);
    padding-bottom: 10px;
    margin-bottom: 24px;
  }}
  section h3 {{
    font-size: 1.25em;
    font-weight: 600;
    color: var(--gold-light);
    margin: 32px 0 14px;
  }}
  section p {{ margin-bottom: 16px; color: var(--text-secondary); }}

  /* ── Charts ── */
  .chart-wrapper {{
    background: var(--card-bg);
    border: 1px solid var(--border);
    border-radius: 12px;
    padding: 28px 24px;
    margin-bottom: 28px;
  }}
  .chart-wrapper h4 {{
    font-size: 1.05em;
    color: var(--gold-light);
    margin-bottom: 16px;
    text-align: center;
  }}
  .chart-inner {{ position: relative; max-height: 380px; }}
  .chart-row {{
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 24px;
    margin-bottom: 28px;
  }}

  /* ── Tables ── */
  .data-table {{
    width: 100%;
    border-collapse: collapse;
    margin-bottom: 28px;
    font-size: 0.92em;
  }}
  .data-table thead th {{
    background: var(--card-bg);
    color: var(--gold);
    font-weight: 600;
    padding: 14px 16px;
    text-align: left;
    border-bottom: 2px solid var(--gold);
    font-size: 0.85em;
    text-transform: uppercase;
    letter-spacing: 0.05em;
  }}
  .data-table tbody td {{
    padding: 12px 16px;
    border-bottom: 1px solid var(--border);
    color: var(--text-secondary);
  }}
  .data-table tbody tr:hover td {{
    background: rgba(200,169,81,0.05);
  }}
  .data-table .highlight {{
    color: var(--gold);
    font-weight: 600;
  }}
  .badge {{
    display: inline-block;
    background: var(--gold);
    color: var(--darker);
    font-weight: 700;
    padding: 2px 10px;
    border-radius: 20px;
    font-size: 0.82em;
    min-width: 28px;
    text-align: center;
  }}

  /* ── Top Composers featured cards ── */
  .composer-hero-grid {{
    display: grid;
    grid-template-columns: repeat(auto-fill, minmax(240px, 1fr));
    gap: 18px;
    margin-bottom: 32px;
  }}
  .composer-hero-card {{
    background: var(--card-bg);
    border: 1px solid var(--border);
    border-radius: 10px;
    padding: 22px 20px;
    text-align: center;
  }}
  .composer-hero-card .comp-name {{
    font-size: 1.2em;
    font-weight: 700;
    color: var(--gold);
    margin-bottom: 4px;
  }}
  .composer-hero-card .comp-wins {{
    font-size: 2em;
    font-weight: 800;
    color: #fff;
    margin-bottom: 6px;
  }}
  .composer-hero-card .comp-era {{
    font-size: 0.8em;
    color: var(--text-secondary);
    text-transform: uppercase;
    letter-spacing: 0.05em;
  }}

  /* ── Callout box ── */
  .callout {{
    background: linear-gradient(135deg, rgba(200,169,81,0.12), rgba(200,169,81,0.04));
    border-left: 4px solid var(--gold);
    padding: 20px 24px;
    border-radius: 0 8px 8px 0;
    margin-bottom: 28px;
    font-size: 0.95em;
  }}
  .callout strong {{ color: var(--gold-light); }}

  /* ── Milestone cards ── */
  .milestone-grid {{
    display: grid;
    grid-template-columns: repeat(3, 1fr);
    gap: 18px;
    margin-bottom: 28px;
  }}
  .milestone-card {{
    background: var(--card-bg);
    border: 1px solid var(--border);
    border-radius: 10px;
    padding: 22px 20px;
  }}
  .milestone-card .ms-year {{
    font-size: 0.8em;
    color: var(--gold);
    text-transform: uppercase;
    letter-spacing: 0.06em;
    margin-bottom: 6px;
  }}
  .milestone-card .ms-title {{
    font-size: 1.05em;
    font-weight: 600;
    color: #fff;
    margin-bottom: 4px;
  }}
  .milestone-card .ms-detail {{
    font-size: 0.88em;
    color: var(--text-secondary);
  }}

  /* ── Footer ── */
  footer {{
    text-align: center;
    padding: 40px 30px;
    border-top: 1px solid var(--border);
    color: var(--text-secondary);
    font-size: 0.85em;
    margin-top: 40px;
  }}

  /* ── Responsive ── */
  @media (max-width: 900px) {{
    .kpi-grid {{ grid-template-columns: repeat(2, 1fr); }}
    .chart-row {{ grid-template-columns: 1fr; }}
    .milestone-grid {{ grid-template-columns: 1fr; }}
    .composer-hero-grid {{ grid-template-columns: repeat(2, 1fr); }}
  }}
  @media (max-width: 560px) {{
    .kpi-grid {{ grid-template-columns: 1fr; }}
    .composer-hero-grid {{ grid-template-columns: 1fr; }}
    .hero h1 {{ font-size: 1.7em; }}
  }}
</style>
</head>
<body>

<!-- ═══════════ HERO ═══════════ -->
<header class="hero">
  <h1>Nine Decades of Oscar-Winning Scores</h1>
  <p class="subtitle">A comprehensive trend analysis of every Academy Award for Best Original Score, 1934–2026 — 93 ceremonies, {total_unique_composers} unique composers, and the evolution of film music's highest honor.</p>
</header>

<div class="container">

<!-- ═══════════ KPI CARDS ═══════════ -->
<div class="kpi-grid">
  <div class="kpi-card">
    <div class="value">{total_unique_composers}</div>
    <div class="label">Unique Composers</div>
  </div>
  <div class="kpi-card">
    <div class="value">{max_wins}</div>
    <div class="label">Max Wins (Single Composer)</div>
  </div>
  <div class="kpi-card">
    <div class="value">{repeat_winner_rate:.0%}</div>
    <div class="label">Repeat Winner Rate</div>
  </div>
  <div class="kpi-card">
    <div class="value">{best_decade}s</div>
    <div class="label">Decade with Most Unique Winners ({best_decade_count})</div>
  </div>
</div>

<!-- ═══════════ SECTION 1: OVERVIEW ═══════════ -->
<section id="overview">
  <h2>Dataset Overview &amp; Historical Context</h2>

  <p>This analysis draws on a definitive dataset of every Academy Award for Best Original Score, spanning 93 consecutive ceremonies from 1934 (the 6th Academy Awards) through 2026 (the 98th ceremony). The dataset normalizes the category's complex administrative history — including years when the Academy split the award into dramatic and comedy/musical subcategories — into a single canonical winner per ceremony year.</p>

