  </div>

  <h3>Decade Summary Table</h3>
  <table class="data-table">
    <thead>
      <tr><th>Decade</th><th>Ceremonies</th><th>Unique Winners</th><th>Repeat Winners (In-Decade)</th><th>Most Awarded</th><th>Wins</th></tr>
    </thead>
    <tbody>
'''

for row in decade_table_rows:
    html += f'''      <tr>
        <td class="highlight">{row['decade']}</td>
        <td>{row['ceremonies']}</td>
        <td><strong>{row['unique']}</strong></td>
