      <div class="ms-detail">{longest_gap[1]} to {longest_gap[2]}. One of the longest intervals between Oscar scoring victories in Academy history.</div>
    </div>
'''

# Add more milestone cards
# Consecutive wins by different composers is notable too
# First female winner: Hildur Guðnadóttir (2019)
hildur_win = [w for w in individual_wins if w['composer'] == 'Hildur Guðnadóttir']
if hildur_win:
    html += f'''    <div class="milestone-card">
