import csv
import json
import math
from collections import Counter, defaultdict

# ── 1. Load & parse data ──────────────────────────────────────────────
rows = []
with open('/app/benchmark/data.csv', 'r', encoding='utf-8') as f:
    reader = csv.DictReader(f)
    for r in reader:
        rows.append({
            'year': int(r['Year']),
            'film': r['Film'].strip(),
            'composer_raw': r['Composer'].strip()
        })

# Split combined composer strings into individual lists
for r in rows:
    r['composers'] = [c.strip() for c in r['composer_raw'].split(',')]

# Build individual-level records for frequency analysis
individual_wins = []  # (year, film, individual_composer)
for r in rows:
    for c in r['composers']:
        individual_wins.append({
            'year': r['year'],
            'film': r['film'],
            'composer': c
        })

# ── 2. KPI computations ──────────────────────────────────────────────

all_composers = sorted(set(w['composer'] for w in individual_wins))
total_unique_composers = len(all_composers)

composer_win_count = Counter(w['composer'] for w in individual_wins)
max_wins = max(composer_win_count.values())
max_win_composers = sorted([c for c, n in composer_win_count.items() if n == max_wins])

# Repeat winner rate: a ceremony counts if ANY of its composers had won before
# Track composers who have won up to (not including) the current year
prior_winners = set()
repeat_ceremony_count = 0
for r in rows:
    is_repeat = any(c in prior_winners for c in r['composers'])
    if is_repeat:
        repeat_ceremony_count += 1
    prior_winners.update(r['composers'])
repeat_winner_rate = repeat_ceremony_count / len(rows)

# Decade with most unique winners
def decade_of(year):
    return (year // 10) * 10

decade_composers = defaultdict(set)
for w in individual_wins:
    dec = decade_of(w['year'])
    decade_composers[dec].add(w['composer'])

decade_unique_counts = {dec: len(composers) for dec, composers in decade_composers.items()}
best_decade = max(decade_unique_counts, key=decade_unique_counts.get)
best_decade_count = decade_unique_counts[best_decade]

# ── 3. Top composers ranking ─────────────────────────────────────────
top_composers = sorted(composer_win_count.items(), key=lambda x: (-x[1], x[0]))

# ── 4. Decade-by-decade breakdown ────────────────────────────────────
decades_info = {}
for dec in sorted(decade_composers.keys()):
    comps = decade_composers[dec]
    wins_in_decade = [w for w in individual_wins if decade_of(w['year']) == dec]
    win_counts_in_decade = Counter(w['composer'] for w in wins_in_decade)
    repeat_wins = sum(1 for c, n in win_counts_in_decade.items() if n > 1)
    decades_info[dec] = {
        'unique_winners': len(comps),
        'total_ceremonies': sum(1 for r in rows if decade_of(r['year']) == dec),
        'repeat_winners': repeat_wins,
        'top_in_decade': win_counts_in_decade.most_common(5)
    }

# ── 5. Era analysis ──────────────────────────────────────────────────
era_boundaries = {
    'Golden Age': (1934, 1959),
    'Silver Age': (1960, 1979),
    'Modern Era': (1980, 1999),
    'Contemporary Era': (2000, 2026)
}

era_analysis = {}
for era_name, (start, end) in era_boundaries.items():
    era_wins = [w for w in individual_wins if start <= w['year'] <= end]
    era_comp_counts = Counter(w['composer'] for w in era_wins)
    era_films = list(dict.fromkeys(w['film'] for w in era_wins))  # unique preserving order
    era_analysis[era_name] = {
        'start': start,
        'end': end,
        'ceremonies': sum(1 for r in rows if start <= r['year'] <= end),
        'unique_composers': len(set(w['composer'] for w in era_wins)),
        'top_composers': era_comp_counts.most_common(5),
        'films': era_films
    }

# ── 6. Notable milestones ────────────────────────────────────────────

# First-time winners (first ceremony year per composer)
composer_first_win = {}
for w in individual_wins:
    if w['composer'] not in composer_first_win:
        composer_first_win[w['composer']] = w['year']

# All wins per composer with years
composer_all_wins = defaultdict(list)
for w in individual_wins:
    composer_all_wins[w['composer']].append(w['year'])

# Longest gaps
gaps = []
for comp, years in composer_all_wins.items():
    if len(years) >= 2:
        sorted_years = sorted(years)
        for i in range(1, len(sorted_years)):
            gaps.append((comp, sorted_years[i-1], sorted_years[i], sorted_years[i] - sorted_years[i-1]))
gaps.sort(key=lambda x: -x[3])
longest_gap = gaps[0] if gaps else None

# Most recent winner info
